     3	public sealed class CashMachine(IMoneyDispenser dispenser) : ICashMachine
     4	{
     5	    private const int DailyLimit = 200;
     6	    private const int FeeThreshold = 100;
     7	    private const int WithdrawalFee = 5;
     8	    private const int MaxNotesPerPass = 4;
     9	    private const int CassetteCapacity = 5;
    10	
    11	    public AtmResult Execute(AccountState account, Operation operation)
    12	    {
    13	        ArgumentNullException.ThrowIfNull(operation);
    14	
    15	        return operation switch
    16	        {
    17	            Operation.Withdraw withdraw => Withdraw(account, withdraw.Amount),
    18	            Operation.Deposit deposit => Deposit(account, deposit.Notes),
    19	            _ => throw new ArgumentException($"Opération inconnue : {operation.GetType().Name}", nameof(operation)),
    20	        };
    21	    }
    22	
    23	    private AtmResult Withdraw(AccountState account, int amount)
    24	    {
    25	        if (amount <= 0 || amount % 10 != 0)
    26	        {
    27	            return Refuse(AtmStatus.InvalidAmount, account);
    28	        }
    29	
    30	        if (account.WithdrawnToday + amount > DailyLimit)
    31	        {
    32	            return Refuse(AtmStatus.DailyLimitExceeded, account);
    33	        }
    34	
    35	        var fee = amount > FeeThreshold ? WithdrawalFee : 0;
    36	        if (amount + fee > account.Balance)
    37	        {
    38	            return Refuse(AtmStatus.InsufficientFunds, account);
    39	        }
    40	
    41	        if (FewestNotes(amount, Available()) is not { } combination)
    42	        {
    43	            return Refuse(AtmStatus.CannotDispense, account);
    44	        }
    45	
    46	        var dispensed = NoteCounts.None;
    47	        foreach (var pass in SplitIntoPasses(combination))
    48	        {
    49	            if (!dispenser.Dispense(pass))
    50	            {
    51	                return new AtmResult(AtmStatus.DispenserFault, dispensed, 0, account);
    52	            }
    53	
    54	            dispensed += pass;
    55	        }
    56	
    57	        var after = new AccountState(account.Balance - amount - fee, account.WithdrawnToday + amount);
    58	
    59	        return new AtmResult(AtmStatus.Ok, combination, fee, after);
    60	    }
    61	
    62	    private AtmResult Deposit(AccountState account, NoteCounts notes)
    63	    {
    64	        if (notes.Fifties < 0 || notes.Twenties < 0 || notes.Tens < 0 || notes.Total == 0)
    65	        {
    66	            return Refuse(AtmStatus.InvalidAmount, account);
    67	        }
    68	
    69	        if (dispenser.Jammed is { } jammed && notes.Of(jammed) > 0)
    70	        {
    71	            return Refuse(AtmStatus.CassetteJammed, account);
    72	        }
    73	
    74	        var after = dispenser.Stock + notes;
    75	        if (after.Fifties > CassetteCapacity || after.Twenties > CassetteCapacity || after.Tens > CassetteCapacity)
    76	        {
    77	            return Refuse(AtmStatus.CassetteFull, account);
    78	        }
    79	
    80	        if (!dispenser.Load(notes))
    81	        {
    82	            return new AtmResult(AtmStatus.DispenserFault, NoteCounts.None, 0, account);
    83	        }
    84	
    85	        return new AtmResult(AtmStatus.Ok, NoteCounts.None, 0, account with { Balance = account.Balance + notes.Value });
    86	    }
    87	
    88	    /// <summary>Le stock, la cassette bloquée comptant pour zéro.</summary>
    89	    private NoteCounts Available()
    90	    {
    91	        var stock = dispenser.Stock;
    92	
    93	        return dispenser.Jammed switch
    94	        {
    95	            Denomination.Fifty => stock with { Fifties = 0 },
    96	            Denomination.Twenty => stock with { Twenties = 0 },
    97	            Denomination.Ten => stock with { Tens = 0 },
    98	            _ => stock,
    99	        };
   100	    }
   101	
   102	    /// <summary>La combinaison exacte qui compte le moins de billets, ou <c>null</c>.</summary>
   103	    private static NoteCounts? FewestNotes(int amount, NoteCounts available)
   104	    {
   105	        NoteCounts? best = null;
   106	        for (var fifties = Math.Min(available.Fifties, amount / 50); fifties >= 0; fifties--)
   107	        {
   108	            var afterFifties = amount - fifties * 50;
   109	            for (var twenties = Math.Min(available.Twenties, afterFifties / 20); twenties >= 0; twenties--)
   110	            {
   111	                var rest = afterFifties - twenties * 20;
   112	                if (rest % 10 != 0 || rest / 10 > available.Tens)
   113	                {
   114	                    continue;
   115	                }
   116	
   117	                var candidate = new NoteCounts(fifties, twenties, rest / 10);
   118	                if (best is not { } current || candidate.Total < current.Total)
   119	                {
   120	                    best = candidate;
   121	                }
   122	            }
   123	        }
   124	
   125	        return best;
   126	    }
   127	
   128	    /// <summary>Découpe la combinaison en passages de 4 billets au plus.</summary>
   129	    private static IEnumerable<NoteCounts> SplitIntoPasses(NoteCounts notes)
   130	    {
   131	        var remaining = notes;
   132	        while (remaining.Total > 0)
   133	        {
   134	            var room = MaxNotesPerPass;
   135	            var fifties = Math.Min(remaining.Fifties, room);
   136	            room -= fifties;
   137	            var twenties = Math.Min(remaining.Twenties, room);
   138	            room -= twenties;
   139	            var tens = Math.Min(remaining.Tens, room);
   140	
   141	            var pass = new NoteCounts(fifties, twenties, tens);
   142	            remaining -= pass;
   143	
   144	            yield return pass;
   145	        }
   146	    }
   147	
   148	    private static AtmResult Refuse(AtmStatus status, AccountState account) =>
   149	        new(status, NoteCounts.None, 0, account);
   150	}
namespace Atm;

public enum Denomination { Fifty = 50, Twenty = 20, Ten = 10 }

public enum AtmStatus
{
    Ok,
    InvalidAmount,
    DailyLimitExceeded,
    InsufficientFunds,
    CannotDispense,
    CassetteJammed,
    CassetteFull,
    DispenserFault,
}

public readonly record struct NoteCounts(int Fifties, int Twenties, int Tens)
{
    public static NoteCounts None => default;
    public int Total => Fifties + Twenties + Tens;
    public int Value => Fifties * 50 + Twenties * 20 + Tens * 10;

    public int Of(Denomination denomination) => denomination switch
    {
        Denomination.Fifty => Fifties,
        Denomination.Twenty => Twenties,
        _ => Tens,
    };

    public static NoteCounts operator +(NoteCounts a, NoteCounts b) =>
        new(a.Fifties + b.Fifties, a.Twenties + b.Twenties, a.Tens + b.Tens);

    public static NoteCounts operator -(NoteCounts a, NoteCounts b) =>
        new(a.Fifties - b.Fifties, a.Twenties - b.Twenties, a.Tens - b.Tens);
}

public readonly record struct AccountState(int Balance, int WithdrawnToday);

public abstract record Operation
{
    public sealed record Withdraw(int Amount) : Operation;

    public sealed record Deposit(NoteCounts Notes) : Operation;
}

public readonly record struct AtmResult(AtmStatus Status, NoteCounts Notes, int Fee, AccountState Account);

public interface IMoneyDispenser
{
    NoteCounts Stock { get; }

    Denomination? Jammed { get; }

    bool Dispense(NoteCounts notes);

    bool Load(NoteCounts notes);
}

public interface ICashMachine
{
    AtmResult Execute(AccountState account, Operation operation);
}
namespace Atm;

/// <summary>Le vrai module de billets, déterministe.</summary>
public sealed class MoneyDispenser(NoteCounts stock, Denomination? jammed = null) : IMoneyDispenser
{
    public const int MaxNotesPerPass = 4;
    public const int CassetteCapacity = 5;

    public NoteCounts Stock { get; private set; } = stock;

    public Denomination? Jammed { get; } = jammed;

    public bool Dispense(NoteCounts notes)
    {
        var enough = notes.Fifties <= Stock.Fifties && notes.Twenties <= Stock.Twenties && notes.Tens <= Stock.Tens;
        if (!IsValid(notes) || notes.Total > MaxNotesPerPass || !enough)
        {
            return false;
        }

        Stock -= notes;

        return true;
    }

    public bool Load(NoteCounts notes)
    {
        var after = Stock + notes;
        var fits = after.Fifties <= CassetteCapacity && after.Twenties <= CassetteCapacity && after.Tens <= CassetteCapacity;
        if (!IsValid(notes) || !fits)
        {
            return false;
        }

        Stock = after;

        return true;
    }

    private bool IsValid(NoteCounts notes) =>
        notes is { Fifties: >= 0, Twenties: >= 0, Tens: >= 0, Total: > 0 }
        && (Jammed is not { } cassette || notes.Of(cassette) == 0);
}
