int[] AllAmounts = [-10, 0, 5, .. Enumerable.Range(1, 22).Select(i => i * 10)];
NoteCounts[] AllDeposits = [.. from f in new[] { 0, 1 } from t in new[] { 0, 1 } from n in new[] { 0, 1 } select new NoteCounts(f, t, n)];
var w = new HashSet<(int,int,int,int,int,int,int)>();
var d = new HashSet<(int,int,int,int,int,int,int,int,int)>();
int J(Denomination? j) => j is null ? 0 : (int)j;
for (int seed=1; seed<=8; seed++){
 var random = new Random(seed);
 AccountState RA() => new(random.Next(51) * 5, random.Next(21) * 10);
 for (var session = 0; session < 200; session++){
  var jammed = AllJams[random.Next(AllJams.Length)];
  var stock = new NoteCounts(random.Next(6), random.Next(6), random.Next(6));
  var disp = new MoneyDispenser(stock, jammed); var m = new CashMachine(disp);
  var account = RA();
  for (var step = 0; step < 40; step++){
   if (random.Next(10) == 0) account = RA();
   Operation op;
   if (random.Next(2) == 0) op = new Operation.Withdraw(AllAmounts[random.Next(AllAmounts.Length)]);
   else { var c = AllDeposits.Where(n => account.Balance + n.Value <= 250).ToArray(); op = new Operation.Deposit(c[random.Next(c.Length)]); }
   var s = disp.Stock;
   if (op is Operation.Withdraw ww) w.Add((account.Balance, account.WithdrawnToday, s.Fifties, s.Twenties, s.Tens, J(jammed), ww.Amount));
   else if (op is Operation.Deposit dd) d.Add((account.Balance, account.WithdrawnToday, s.Fifties, s.Twenties, s.Tens, J(jammed), dd.Notes.Fifties, dd.Notes.Twenties, dd.Notes.Tens));
   account = m.Execute(account, op).Account;
  }
 }
}
