File.WriteAllLines("/tmp/cov/d.txt", d.Select(x => string.Join(",", x.Item1,x.Item2,x.Item3,x.Item4,x.Item5,x.Item6,x.Item7,x.Item8,x.Item9)));
// stats: withdraw reaching check4 (daily ok, funds ok, amount valid) by stock
var reach = w.Where(x => x.Item7>0 && x.Item7%10==0 && x.Item2+x.Item7<=200 && x.Item7+(x.Item7>100?5:0)<=x.Item1).ToList();
Console.WriteLine($"reach check4: {reach.Count}");
var insuff = w.Where(x => x.Item7>0 && x.Item7%10==0 && x.Item2+x.Item7<=200 && x.Item7+(x.Item7>100?5:0)>x.Item1).ToList();
Console.WriteLine($"insufficient: {insuff.Count}");
