import subprocess, sys, re
orig = open('/tmp/mut/orig.cs').read()
lines = orig.split('\n')
subs_amount = ['account.Balance', 'account.Balance - fee', '(DailyLimit - account.WithdrawnToday)', '(amount + fee)', 'account.WithdrawnToday']
muts = []
# token substitutions of 'amount' in Withdraw lines 25..59 (1-based)
for i in range(24, 59):
    l = lines[i]
    for m in re.finditer(r'\bamount\b', l):
        for s in subs_amount:
            muts.append((i, l[:m.start()] + s + l[m.end():]))
    for m in re.finditer(r'\bfee\b', l):
        for s in ['0', 'WithdrawalFee']:
            muts.append((i, l[:m.start()] + s + l[m.end():]))
    for m in re.finditer(r' (>|<|>=|<=) ', l):
        alt = {'>':'>=','>=':'>','<':'<=','<=':'<'}[m.group(1)]
        muts.append((i, l[:m.start()] + ' ' + alt + ' ' + l[m.end():]))
def run(i, newl):
    ls = list(lines); ls[i] = newl
    open('/travail/Atm/CashMachine.cs','w').write('\n'.join(ls))
    r = subprocess.run('cd /travail && dotnet build Atm.Tests -v q 2>&1 | grep -c " error " ; dotnet test --no-build 2>&1 | tail -1', shell=True, capture_output=True, text=True)
    return r.stdout.strip().replace('\n',' | ')
try:
    for i, nl in muts:
        out = run(i, nl)
        if 'Passed!' in out or 'Failed: ' not in out:
            print('SURVIVE/ERR', i+1, nl.strip(), out[-120:], flush=True)
finally:
    open('/travail/Atm/CashMachine.cs','w').write(orig)
print('done', len(muts))
EOF
