import itertools
reps=[(0,0,0),(5,5,5),(5,0,0),(0,5,0),(0,0,5),(1,3,0),(1,1,1),(4,0,0),(3,2,1),(2,4,3)]
def avail(s,j):
    s=list(s)
    if j is not None: s[j]=0
    return tuple(s)
def best(a,av):
    b=None
    for f in range(av[0]+1):
        for t in range(av[1]+1):
            for n in range(av[2]+1):
                if 50*f+20*t+10*n==a:
                    if b is None or f+t+n<sum(b): b=(f,t,n)
    return b
jams=[None,0,1,2]
allst=list(itertools.product(range(6),repeat=3))
for a in range(10,201,10):
    allc={}; repc=set()
    for s in allst:
        for j in jams:
            c=best(a,avail(s,j)); allc[c]=allc.get(c,0)+1
            if s in reps: repc.add(c)
    miss={c:k for c,k in allc.items() if c not in repc}
    print(a, 'missing in reps:', miss)
EOF
